99	int8_t ApiConnector::handle_async() {
100	  const unsigned long time_at_send = millis();
101	
102	  char url[100];
103	  sprintf(url, "%s?api_key=%s&", TTSERVE_MEASUREMENTS_ENDPOINT, _config.get_api_key());
104	
105	  //Specify destination for HTTP request
106	  if (!_http_client.begin(url)) {
107	    M5_LOGD("Unable to begin url connection");
108	    _http_client.end(); //Free resources
109	    return e_api_reporter_error_remote_not_available;
110	  }
111	
112	  char content_length[5];
113	
114	  sprintf(content_length, "%d", strlen(_payload));
115	
116	  _http_client.setUserAgent(HEADER_API_USER_AGENT);
117	  _http_client.addHeader("Host", TTSERVE_HOST);
118	  _http_client.addHeader("Content-Type", "application/json");
119	  _http_client.addHeader("Content-Length", content_length);
120	
121	  int httpResponseCode = _http_client.POST(_payload);
122	
123	  String response = _http_client.getString();
124	  M5_LOGD("POST complete, response (%d):\n%s\n", httpResponseCode, response.c_str());
125	  _http_client.end(); //Free resources
126	
127	  // TODO: Check response measurement ID
128	
129	  WiFiWrapper_i.update_active();
130	  _last_post = time_at_send;
131	
132	  switch (httpResponseCode) {
133	    case 200 ... 204:
134	      ++_post_count;
135	      return e_api_reporter_send_success;
136	    case 400:
137	      return e_api_reporter_error_server_rejected_post_400;
138	    case 401:
139	      return e_api_reporter_error_server_rejected_post_401;
140	    case 403:
141	      return e_api_reporter_error_server_rejected_post_403;
142	    case 500 ... 599:
143	      return e_api_reporter_error_server_rejected_post_5xx;
144	    default:
145	      return e_api_reporter_error_remote_not_available;
146	  }
147	}

